static void qm047ks01_init(void)
{
    int i;
    struct dsi_cmd_packet qm047ks01_display_on = {0x05, 0x29, 0x00};

    for (i = 0; i < ARRAY_SIZE(fitipower_qm047ks01_cmd_list); i++)
        dsi_write_cmd(&fitipower_qm047ks01_cmd_list[i]);

    msleep(200);
    dsi_write_cmd(&qm047ks01_display_on);
    msleep(20);
}

static inline int m_gpio_request(int gpio, const char *name)
{
    if (gpio < 0)
        return 0;

    int ret = gpio_request(gpio, name);
    if (ret) {
        char buf[20];
        printk(KERN_ERR "qm047ks01: failed to request %s: %s\n", name, gpio_to_str(gpio, buf));
        return ret;
    }

    return 0;
}

static inline void m_gpio_free(int gpio)
{
    if (gpio >= 0)
        gpio_free(gpio);
}

static inline void m_gpio_direction_output(int gpio, int value)
{
    if (gpio >= 0)
        gpio_direction_output(gpio, value);
}

static inline void m_gpio_direction_input(int gpio)
{
    if (gpio >= 0)
        gpio_direction_input(gpio);
}

static int qm047ks01_power_on(struct lcdc *lcdc)
{
    if (qm047ks01_regulator)
        regulator_enable(qm047ks01_regulator);

    m_gpio_direction_output(gpio_lcd_power_en, 1);
    msleep(10);

    m_gpio_direction_output(gpio_lcd_rst, 1);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    msleep(120);
    m_gpio_direction_output(gpio_lcd_rst, 1);
    msleep(10);

    m_gpio_direction_output(gpio_lcd_backlight_en, 1);

    return 0;
}

static int qm047ks01_power_off(struct lcdc *lcdc)
{
    if (qm047ks01_regulator)
        regulator_disable(qm047ks01_regulator);

    m_gpio_direction_output(gpio_lcd_backlight_en, 0);
    m_gpio_direction_output(gpio_lcd_rst, 0);
    m_gpio_direction_output(gpio_lcd_power_en, 0);

    return 0;
}

